// launch-factory: Better Auth 조립. getAuth() = 요청 처리기(경로용), authPort() = 계약 AuthPort 어댑터(서버 액션용).
// 요청 제한 저장소는 DB 다. 가입 폼은 Cloudflare Turnstile 로 봇을 거른다(mock 은 통과, live 는 TURNSTILE_SECRET_KEY 필수).
import { randomBytes } from "node:crypto"
import { cookies, headers } from "next/headers"
import { after } from "next/server"
import { authAdapter, createAuth, notMeToken, SOCIAL_ENV_NAMES, socialsFromEnv, type Auth, type AuthIO, type LaunchAuthPort } from "@launch-factory/auth"
import { authEmails } from "@launch-factory/email"
import { readSecrets } from "@launch-factory/env"
import { ipAddressFromEnv } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { appUrl, CONSENT_VERSIONS, DEFAULT_LOCALE, PRODUCT_NAME, ROUTES } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { hasUrl } from "@/lib/launch/enabled"
import { AUTH_FEATURES } from "@/lib/launch/features"
import { env, required } from "@/lib/launch/env"
import { linkSecret } from "@/lib/launch/link-secret"
import { mailer } from "@/lib/launch/mailer"
import { sendMarketingNotice } from "@/lib/launch/notices"

/**
 * mock 에서 BETTER_AUTH_SECRET 이 없으면 프로세스마다 새로 만든다(고정값을 코드에 두지 않는다 — 재시작하면 로그인이 풀린다). live 는 32자 이상이 필수다.
 * 모듈 변수가 아니라 globalThis 에 둔다: 서버 번들이 쪽·서버 액션·경로 처리기로 갈라져 같은 모듈이 번들마다 따로 불리므로, 모듈 변수에 두면 번들마다 다른 비밀키로
 * 쿠키에 서명해 /api/auth 가 준 로그인이 쪽에서 검증되지 않는다(lib/launch/db.ts 의 mock DB 와 같은 까닭).
 */
const mockAuthSecret = globalThis as { __lfMockAuthSecret?: string }
const mockSecret = () => (mockAuthSecret.__lfMockAuthSecret ??= randomBytes(32).toString("hex"))

/**
 * 메일 발송은 응답을 기다리지 않는다(대장 D202 — Better Auth 공식 문서: 기다리면 있는 계정만 느려져 이메일 존재 여부가 시간으로 드러난다).
 * Next 의 after 가 응답 뒤에도 서버리스 함수를 살려 발송을 끝낸다(Vercel 에서는 waitUntil 로 구현된다). 요청 밖이면 after 가 던지므로 그냥 백그라운드로 둔다.
 */
function runInBackground(task: Promise<unknown>): void {
  try {
    after(task)
  } catch {
    void task
  }
}

/** 소셜 로그인이 실패하면 돌아오는 화면(?error=signup_disabled 등이 붙는다). 이 화면이 안내를 보인다(app/(product)/sign-in/page.tsx) */
export const SOCIAL_ERROR_PATH = "/sign-in"

/**
 * 확인 메일의 링크를 누르면 닿는 곳(UXOK). `?welcome=verified` 표지를 보고 도착 화면이 「확인됐어요」를 한 번 보인다(components/product/welcome-notice.tsx).
 * 그 안내를 만들지 않은 제품은 이 줄을 `"/"` 로 바꾼다. 링크가 틀리면 Better Auth 가 같은 주소에 `error=` 를 덧붙인다.
 */
export const EMAIL_VERIFIED_PATH = "/?welcome=verified"

let cached: Promise<Auth> | undefined

export function getAuth(): Promise<Auth> {
  return (cached ??= build())
}

async function build(): Promise<Auth> {
  const e = env()
  const live = e.LF_MODE === "live"
  const emails = authEmails(mailer(), {
    productName: PRODUCT_NAME,
    defaultLocale: DEFAULT_LOCALE,
    securityUrl: `${appUrl()}${ROUTES.security}`,
    // C02: 비밀번호·이메일 변경 알림의 「문의하기」 버튼 — 문의 화면이 없는 제품(문의를 고르지 않음)은 버튼을 싣지 않는다(contactUrl 은 선택이다)
    contactUrl: hasUrl(ROUTES.contact) ? `${appUrl()}${ROUTES.contact}` : undefined,
    // G05: 이메일을 확인한 뒤 한 번 보내는 환영 메일의 「열기」 링크
    appUrl: appUrl(),
    // A13: 확인 메일의 「제가 가입한 게 아니에요」 — 서명 토큰 링크(확인 화면 /email 을 거쳐 아직 확인 안 된 그 계정만 지운다)
    notMeUrl: (r) => (r.id ? `${appUrl()}/api/account/not-me?t=${notMeToken(r.id, linkSecret())}` : undefined),
  })
  // 소셜 로그인: 공급자마다 <P>_CLIENT_ID·<P>_CLIENT_SECRET 둘 다 있을 때만 켠다(live·mock 같은 규칙). 하나만 있으면 켜지 않는다 — 이름만 알린다(값은 싣지 않는다).
  // 키는 프로세스 환경 → Windows 사용자 환경 순으로 읽는다(doctor 와 같은 순서라 doctor 가 통과하면 앱도 켜진다).
  const socialEnv = readSecrets(SOCIAL_ENV_NAMES)
  const { enabled: socials, partial } = socialsFromEnv(socialEnv)
  for (const { provider, missing } of partial) console.warn(`[auth] ${provider} sign-in is off: missing ${missing.join(", ")} (both CLIENT_ID and CLIENT_SECRET are needed)`)
  return createAuth({
    db: await database(),
    secret: live ? required("BETTER_AUTH_SECRET") : (e.BETTER_AUTH_SECRET ?? mockSecret()),
    baseURL: appUrl(),
    consentVersions: CONSENT_VERSIONS,
    socials,
    env: socialEnv,
    // 선택 조각(lib/launch/features.ts). 관리자는 2단계 인증이 필요해 둘이 함께 켜진다(feature-admin)
    twoFactor: AUTH_FEATURES.twoFactor,
    admin: AUTH_FEATURES.admin,
    botCheck: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    // 재설정 메일(sendResetPassword)을 포함한 계정 보안 메일 다섯이 authEmails 로 나간다(D180). 보내기 실패는 Better Auth 가 onError 로만 알린다.
    mailer: emails,
    runInBackground,
    // A06: 가입 때 마케팅 수신에 동의했으면 처리 결과 통지 메일(정보통신망법 제50조제7항 · 시행령 제62조의2 — 14일 안에 전송자·사실과 날짜·결과). 설정 화면의 통지(lib/launch/consents.ts)와 같은 메일이다.
    // 보내기가 실패하면 발신함에 남고 Cron(/api/cron/notices)이 다시 보낸다(D210). 가입은 되돌리지 않는다.
    onSignUpMarketing: (e) => sendMarketingNotice({ userId: e.userId, changes: e.changes, at: e.at }, "sign_up"),
    // 요청 제한이 믿을 IP 머리(대장 D205). 요청 제한 항목·문의 항목과 같은 함수라 같은 사람을 같은 IP 로 센다
    ipAddress: ipAddressFromEnv(process.env),
  })
}

type Cookie = { name: string; value: string; path?: string; domain?: string; maxAge?: number; expires?: Date; httpOnly?: boolean; secure?: boolean; sameSite?: "lax" | "strict" | "none" }

/** Set-Cookie 한 줄 → cookies().set 인자. Better Auth 는 값을 URL 인코딩해 보내므로 한 번 풀어 넘긴다(Next 가 다시 인코딩한다) */
function parseSetCookie(line: string): { cookie: Cookie; raw: string } {
  const [pair = "", ...attrs] = line.split(";").map((s) => s.trim())
  const eq = pair.indexOf("=")
  const name = pair.slice(0, eq)
  const raw = pair.slice(eq + 1)
  const cookie: Cookie = { name, value: decodeURIComponent(raw) }
  for (const attr of attrs) {
    const [k = "", v = ""] = attr.split("=")
    switch (k.toLowerCase()) {
      case "path": cookie.path = v; break
      case "domain": cookie.domain = v; break
      case "max-age": cookie.maxAge = Number(v); break
      case "expires": cookie.expires = new Date(v); break
      case "httponly": cookie.httpOnly = true; break
      case "secure": cookie.secure = true; break
      case "samesite": cookie.sameSite = v.toLowerCase() as Cookie["sameSite"]; break
    }
  }
  return { cookie, raw }
}

/** 요청 하나에 붙는 입출력. 이 요청에서 방금 받은 쿠키는 다음 headers() 호출부터 보인다(로그아웃 뒤 session() 이 null 이 되도록) */
export async function authIO(): Promise<AuthIO> {
  const fresh = new Map<string, string | null>()
  return {
    async headers() {
      const h = new Headers(await headers())
      if (fresh.size) {
        const kept = (h.get("cookie") ?? "").split(";").map((s) => s.trim()).filter((c) => c && !fresh.has(c.split("=")[0] ?? ""))
        for (const [name, raw] of fresh) if (raw !== null) kept.push(`${name}=${raw}`)
        h.set("cookie", kept.join("; "))
      }
      return h
    },
    async setCookies(lines) {
      const store = await cookies()
      for (const line of lines) {
        const { cookie, raw } = parseSetCookie(line)
        const { name, value, ...options } = cookie
        store.set(name, value, options)
        fresh.set(name, (options.maxAge ?? 1) <= 0 || value === "" ? null : raw)
      }
    },
  }
}

export async function authPort(): Promise<LaunchAuthPort> {
  // 재설정 메일 링크는 /reset-password?token=… 로 닿는다(LFFIX F4 — 그 쪽은 제품이 만든다. 안 만들었으면 이 줄을 지운다)
  return authAdapter(await getAuth(), await authIO(), { callbackURL: "/", errorCallbackURL: SOCIAL_ERROR_PATH, locale: DEFAULT_LOCALE, resetPasswordPath: "/reset-password", emailVerifiedPath: EMAIL_VERIFIED_PATH })
}

// launch-factory: 인증의 선택 조각 스위치. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
// admin 은 twoFactor 가 필요하다(관리자는 2단계 인증을 켠 사람뿐이다). 둘 다 꺼져 있으면 관리자 경로는 열리지 않는다(feature-admin 이 이유를 알린다).
export const AUTH_FEATURES: { twoFactor: boolean; admin: boolean } = { twoFactor: false, admin: false }

// launch-factory: 관리 화면 구획 — 사용자(계획 3d). 관리자만 들어온다(역할 admin + 2단계 인증 + 정지 아님 + 대리 세션 아님 — 콘솔이 먼저 판정한다).
// 구획은 선언이다 — 접근 벽·확인 입력 벽·기록·연락처 가리기는 콘솔(@launch-factory/admin-console)이 한다. 등록은 lib/launch/admin-console.ts 의 ADMIN_SECTIONS 한 줄.
// 읽고 쓰는 일은 인증 패키지의 관리자 서비스(adminActions)를 직접 부른다 — 그 서비스는 자기 관리자 벽(세션 쿠키로 다시 판정)과 기록(admin_actions)을 가진다(두 겹).
// 이 구획 밖으로 AdminResult 의 코드(admin_required · unauthenticated …)가 새지 않게 아래 refusalOf 한 곳에서 콘솔의 거절 코드로 옮긴다.
// 보이는 것: 표(이메일·이름은 가려서, 역할·정지 여부·2단계 여부·가입일) → 기록(계정 칸 + 세션 수 + 최근 관리자 행동). 비밀번호 해시·세션 토큰·소셜 토큰은 읽지도 않는다.
// 행동: 정지(ban, 위험 — 모든 세션이 끊기고 로그인이 막힌다) · 해제(unban). 정지 사유·기한은 입력을 받지 않는다(기록 행동 단추는 입력을 못 싣는다) — 풀 때까지 정지다.
// 대리 로그인·일괄 정지·CSV 는 콘솔에 없다(feature-admin 의 서버 액션이 맡는다). 정지는 두 입구(이 구획 · feature-admin 의 banUser)가 같은 벽을 지난다 — 인증 서비스가 `confirmed: true` 없이는 실행하지 않는다.
import { adminActions, type AdminActions, type AdminErrorCode, type AdminFailure, type AdminUserDetail, type AdminUserRow } from "@launch-factory/auth"
import { defineSection, refuse, type Refusal } from "@launch-factory/admin-console"
import { authIO, getAuth } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { AUTH_FEATURES } from "@/lib/launch/features"

const STATUSES = ["active", "banned"] as const
/** 인증 서비스의 한 쪽 최대 줄 수(PAGE_SIZE_MAX) */
const MAX_ROWS = 100

/** 인증 서비스의 실패 코드 → 콘솔의 거절 코드. 이 표 밖(새 코드)이 생기면 타입 검사가 여기서 멈춘다 */
const CODES = {
  unauthenticated: "sign_in_required",
  admin_required: "forbidden",
  admin_two_factor_required: "two_factor_required",
  impersonation_blocked: "impersonation_blocked",
  invalid_input: "invalid_input",
  reason_required: "invalid_input",
  export_too_large: "invalid_input",
  not_found: "not_found",
  cannot_ban_self: "invalid_state",
  confirmation_required: "confirmation_required",
  cannot_impersonate_admin: "invalid_state",
  not_impersonating: "invalid_state",
  rate_limited: "action_failed",
  unavailable: "provider_unavailable",
} as const satisfies Record<AdminErrorCode, string>

/** 문구는 인증 서비스가 고정 글로 만든 것(DB 글·개인정보 없음)이라 사람이 읽을 이유가 있는 두 갈래만 싣는다 */
const refusalOf = (f: AdminFailure): Refusal => {
  const code = CODES[f.code]
  return code === "invalid_state" || code === "action_failed" ? refuse(code, f.formError ? { formError: f.formError } : {}) : refuse(code)
}

/** 인증 서비스: 요청마다 만든다(세션 쿠키·머리는 요청 것). 관리자 조각이 꺼져 있으면 provider_unavailable */
async function service(): Promise<AdminActions> {
  return adminActions({ auth: await getAuth(), db: await database(), io: await authIO(), locale: DEFAULT_LOCALE })
}

const yesNo = (v: boolean): string => (v ? "on" : "off")
const day = (iso: string | null): string | null => (iso ? iso.slice(0, 10) : null)
const stamp = (iso: string | null, none = "—"): string => (iso ? `${iso.slice(0, 16).replace("T", " ")} UTC` : none)

export default defineSection({
  id: "users",
  part: "auth",
  label: "Users",
  audience: "admin",
  available: () => AUTH_FEATURES.admin && AUTH_FEATURES.twoFactor,
  statuses: STATUSES,
  serverSearch: true, // 서버 검색이 가린 이메일·이름·번호를 맞춘다(listUsers q — 이메일·이름·번호)
  columns: [
    { id: "email", label: "Email", kind: "contact", primary: true },
    { id: "name", label: "Name", kind: "contact", secondary: true },
    { id: "role", label: "Role", kind: "text" },
    { id: "status", label: "Status", kind: "status", filter: true },
    { id: "twoFactor", label: "2-step", kind: "text", secondary: true },
    { id: "createdAt", label: "Joined", kind: "date", secondary: true },
  ],
  pageSize: MAX_ROWS,
  list: async (_actor, { search, status, limit, offset }) => {
    const size = Math.min(limit, MAX_ROWS)
    const r = await (await service()).listUsers({ ...(search ? { q: search } : {}), ...(status ? { filter: { banned: status === "banned" } } : {}), page: Math.floor(offset / size) + 1, pageSize: size })
    return r.ok ? { items: r.data.rows, total: r.data.total } : refusalOf(r)
  },
  key: (row: AdminUserRow) => row.id,
  cells: (row) => ({ email: row.email, name: row.name, role: row.role, status: row.banned ? "banned" : "active", twoFactor: yesNo(row.twoFactorEnabled), createdAt: day(row.createdAt) }),
  load: async (_actor, id): Promise<AdminUserDetail | null | Refusal> => {
    const r = await (await service()).userDetail({ userId: id })
    if (r.ok) return r.data
    return r.code === "not_found" ? null : refusalOf(r)
  },
  view: ({ user, sessions, recentActions }) => ({
    // 제목은 주소·화면 머리에 그대로 나가므로 이메일·이름 대신 사용자 번호 앞자리를 쓴다
    title: `User ${user.id.slice(0, 8)}`,
    summary: [
      { label: "Email", value: user.email ?? "(none — social sign-in)" },
      { label: "Name", value: user.name },
      { label: "Role", value: user.role },
      { label: "Status", value: user.banned ? "banned" : "active", kind: "status" },
      ...(user.banned ? [{ label: "Ban reason", value: user.banReason ?? "—" }, { label: "Ban ends", value: stamp(user.banExpires, "Until lifted") }] : []),
      { label: "2-step sign-in", value: yesNo(user.twoFactorEnabled) },
      { label: "Email verified", value: user.emailVerified ? "yes" : "no" },
      { label: "Joined", value: stamp(user.createdAt) },
      { label: "Active sessions", value: String(sessions.active), kind: "numeric" },
      { label: "Impersonation sessions", value: String(sessions.impersonation), kind: "numeric" },
      ...recentActions.slice(0, 5).map((a) => ({ label: "Admin action", value: `${a.action} · ${stamp(a.occurredAt)}` })),
    ],
  }),
  actions: {
    ban: {
      label: "Ban user",
      danger: true,
      adminOnly: true,
      when: ({ user }) => !user.banned,
      run: async (_actor, { user }) => {
        const r = await (await service()).banUser({ userId: user.id, confirmed: true }) // 콘솔의 확인 벽(danger)을 지난 뒤라 서비스의 확인 벽에도 확인을 싣는다
        return r.ok ? { message: "User banned. All sessions were ended." } : refusalOf(r)
      },
    },
    unban: {
      label: "Lift ban",
      adminOnly: true,
      when: ({ user }) => user.banned,
      run: async (_actor, { user }) => {
        const r = await (await service()).unbanUser({ userId: user.id })
        return r.ok ? { message: "Ban lifted." } : refusalOf(r)
      },
    },
  },
})

// launch-factory: Better Auth 요청 처리기. 요청 제한(rate_limit)·봇 방어(botCheck)는 이 처리기(auth.handler)에서만 걸린다 —
// 그래서 인증 경로는 모두 여기로 들어온다. 429 응답에는 기계가 읽는 code·retryAfter 를 더한다(LFAX H07 — Better Auth 는 글만 준다).
import { withMachineCodes } from "@launch-factory/auth"
import { getAuth } from "@/lib/launch/auth"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  return withMachineCodes(await (await getAuth()).handler(request))
}

export async function POST(request: Request) {
  return withMachineCodes(await (await getAuth()).handler(request))
}

"use server"
// launch-factory: 인증 서버 액션. 공개 입구다 — 폼(FormData)이든 객체든 authActions 가 모양을 먼저 검사하고 포트로 넘긴다.
// 로그인한 사용자 자신에게만 작용한다(세션 쿠키). 대상 사용자 id 를 입력으로 받지 않는다.
import { authActions } from "@launch-factory/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { authPort } from "@/lib/launch/auth"

const actions = async () => authActions(await authPort(), { locale: DEFAULT_LOCALE })

export async function signIn(input: unknown) {
  return (await actions()).signIn(input)
}
export async function signUp(input: unknown) {
  return (await actions()).signUp(input)
}
export async function resetPassword(input: unknown) {
  return (await actions()).resetPassword(input)
}
export async function signOut() {
  return (await actions()).signOut()
}
export async function verifyTwoFactor(input: unknown) {
  return (await actions()).verifyTwoFactor(input)
}
export async function changePassword(input: unknown) {
  return (await actions()).changePassword(input)
}
export async function changeEmail(input: unknown) {
  return (await actions()).changeEmail(input)
}
export async function sendVerificationEmail(input?: unknown) {
  return (await actions()).sendVerificationEmail(input)
}
export async function listSessions() {
  return (await actions()).listSessions()
}
export async function revokeSession(input: unknown) {
  return (await actions()).revokeSession(input)
}
export async function revokeOtherSessions() {
  return (await actions()).revokeOtherSessions()
}
export async function updatePreferences(input: unknown) {
